///|
async fn save_diagnostic(
  stage : String,
  status : String,
  exit_code? : Int32,
  error_type? : String,
  phase? : String,
  duration_ms? : Double,
  attempt? : Int32,
  retry_delay_ms? : Int32,
  os_errno? : Int32,
  source? : CreateEvidence,
) -> Unit {
  if @env.get_env_var("ORCA_ENV_DEVSY_RECORDING") == Some("0") {
    return
  }
  try {
    let dir = adapter_state_home()
    @fs.mkdir(dir, permission=0o700, recursive=true, allow_exist=true)
    @fs.chmod(dir, 0o700)
    let path = dir + "/events.jsonl"
    if @fs.exists(path) &&
      @fs.kind(path, follow_symlink=false) != @fs.FileKind::Regular {
      return
    }
    if @fs.exists(path) && @fs.file_size(path) > 262144L {
      @fs.remove(path)
    }
    let event : Json = {
      "stage": stage,
      "status": status,
      "time": @env.now().to_string(),
      "runId": recording_run_id,
      "adapterVersion": version,
    }
    if create_recording.attempt > 0 {
      set_field(
        event,
        "createAttempt",
        Json::number(create_recording.attempt.to_double()),
      )
      set_field(event, "createPhase", Json::string(create_recording.phase))
    }
    if source is Some(evidence) {
      set_field(event, "source", evidence.to_json())
    }
    if os_errno is Some(code) && code > 0 && code < 4096 {
      set_field(event, "osErrno", Json::number(code.to_double()))
    }
    if exit_code is Some(code) {
      set_field(event, "exitCode", Json::number(code.to_double()))
    }
    for pair in [("errorType", error_type), ("phase", phase)] {
      if pair.1 is Some(text) {
        set_field(event, pair.0, Json::string(text))
      }
    }
    if duration_ms is Some(value) {
      set_field(event, "durationMs", Json::number(value))
    }
    if attempt is Some(value) {
      set_field(event, "attempt", Json::number(value.to_double()))
    }
    if retry_delay_ms is Some(value) {
      set_field(event, "retryDelayMs", Json::number(value.to_double()))
    }
    @fs.write_file(
      path,
      event.stringify() + "\n",
      permission=0o600,
      append=true,
      create_mode=@fs.OpenOrCreate,
    )
  } catch {
    _ => ()
  }
}

///|
let recording_run_id : String = @env.now().to_string()

///|
fn process_error_type(output : String) -> String {
  let text = output.to_lower()
  if text.contains("out of memory") || text.contains("cannot allocate memory") {
    "memory_exhausted"
  } else if text.contains("no space left on device") {
    "disk_exhausted"
  } else if text.contains("address already in use") ||
    text.contains("addrinuse") {
    "address_in_use"
  } else if text.contains("permission denied (publickey") ||
    text.contains("authentication failed") {
    "authentication_failed"
  } else if text.contains("host key verification failed") {
    "host_key_failed"
  } else if text.contains("connection refused") {
    "connection_refused"
  } else if text.contains("connection timed out") ||
    text.contains("operation timed out") {
    "connection_timeout"
  } else if text.contains("could not resolve hostname") {
    "name_resolution"
  } else if text.contains("controlsocket") || text.contains("control socket") {
    "control_socket"
  } else if text.contains("build_vm:") {
    "vm_boot"
  } else if text.contains("create microsandbox vm") && text.contains("network:") {
    "vm_network"
  } else if text.contains("create microsandbox vm") && text.contains("mount:") {
    "vm_mount"
  } else if text.contains("ensure microsandbox final image") ||
    text.contains("prepare microsandbox final image") {
    "vm_image"
  } else if text.contains("create microsandbox vm") {
    "vm_create"
  } else if text.contains("start microsandbox vm") {
    "vm_start"
  } else if text.contains("no such file or directory") ||
    text.contains("not found") {
    "missing_resource"
  } else if text.contains("permission denied") {
    "permission_denied"
  } else if text.contains("database is locked") ||
    text.contains("database locked") {
    "database_locked"
  } else if text.contains("too many open files") {
    "file_limit"
  } else {
    "process_exit"
  }
}

///|
async fn tunnel_errors(reader : @process.ReadFromProcess) -> String {
  defer reader.close()
  let mut tail = ""
  while reader.read_some(max_len=4096) is Some(bytes) {
    // Decode chunks lossy: arbitrary process stderr need not be valid UTF-8.
    let chunk = @utf8.decode_lossy(bytes)
    tail += chunk
    if tail.length() > 8192 {
      tail = tail[tail.length() - 8192:].to_owned()
    }
  }
  process_error_type(tail)
}

///|
priv struct CreateRecording {
  mut attempt : Int32
  mut phase : String
}

///|
let create_recording : CreateRecording = {
  attempt: 0,
  phase: "input-validation",
}

///|
priv enum CreateEvidence {
  Inputs
  Configuration(String, String, String?)
  Selection(String, String, String?, String, String)
  Clone(String?, String, String, String?)
  AcquiredCommit(String)
  Checkout(String, String)
}

///|
priv enum DiagnosticValueKind {
  Identity
  Workspace
  RefName
  Commit
}

///|
fn diagnostic_value(value : String?, kind : DiagnosticValueKind) -> Json {
  match value {
    None => { "state": "unset" }
    Some("") => { "state": "empty" }
    Some(text) => {
      let valid = match kind {
        Commit => valid_commit(text)
        Workspace => valid_workspace_id(text)
        Identity => text.length() <= 128 && valid_context(text)
        RefName => diagnostic_ref(text)
      }
      if valid {
        { "state": "valid", "value": text }
      } else {
        { "state": "invalid" }
      }
    }
  }
}

///|
// A recording grammar, never a replacement for checkout validation. Excludes
// URLs, credential forms, control characters and Git's invalid ref syntax.
fn diagnostic_ref(text : String) -> Bool {
  text.length() <= 1024 &&
  !text.has_prefix("-") &&
  !text.contains("..") &&
  text
  .split("/")
  .iter()
  .all(part => {
    part != "" &&
    !part.has_prefix(".") &&
    !part.has_suffix(".") &&
    !part.has_suffix(".lock")
  }) &&
  text
  .iter()
  .all(c => {
    (c >= 'a' && c <= 'z') ||
    (c >= 'A' && c <= 'Z') ||
    (c >= '0' && c <= '9') ||
    c == '/' ||
    c == '-' ||
    c == '_' ||
    c == '.'
  })
}

///|
fn CreateEvidence::to_json(self : CreateEvidence) -> Json {
  match self {
    Inputs => {
      let inputs = Json::empty_object()
      for
        (name, kind) in [
          ("ORCA_VM_INSTANCE_ID", Workspace),
          ("ORCA_RECIPE_ID", Identity),
          ("ORCA_REPO_REF", RefName),
          ("ORCA_REPO_REF_HEAD", Commit),
          ("ORCA_REPO_BRANCH", RefName),
        ] {
        set_field(inputs, name, diagnostic_value(@env.get_env_var(name), kind))
      }
      inputs
    }
    Configuration(mode, connection, build_ref) =>
      {
        "checkoutMode": if mode == "orca-worktree" || mode == "provisioned-root" {
          Json::string(mode)
        } else {
          Json::string("invalid")
        },
        "connection": connection,
        "configuredBuildRef": diagnostic_value(build_ref, RefName),
      }
    Selection(build_ref, lookup_ref, branch, commit, reason) =>
      {
        "buildRef": diagnostic_value(Some(build_ref), RefName),
        "lookupRef": diagnostic_value(Some(lookup_ref), RefName),
        "resolvedBranch": diagnostic_value(branch, RefName),
        "resolvedCommit": diagnostic_value(Some(commit), Commit),
        "selectionReason": reason,
      }
    Clone(branch, commit, strategy, reason) =>
      {
        "sourceKind": if branch is Some(_) {
          "branch"
        } else {
          "commit"
        },
        "branch": diagnostic_value(branch, RefName),
        "commit": diagnostic_value(Some(commit), Commit),
        "cloneStrategy": strategy,
        "fallback": reason is Some(_),
        "fallbackReason": match reason {
          Some(value) => Json::string(value)
          None => Json::null()
        },
      }
    AcquiredCommit(actual) =>
      {
        "scope": "build-checkout",
        "actualCommit": diagnostic_value(Some(actual), Commit),
      }
    Checkout(actual, expected) =>
      {
        "scope": "build-checkout",
        "actualCommit": diagnostic_value(Some(actual), Commit),
        "expectedCommit": diagnostic_value(Some(expected), Commit),
        "matches": valid_commit(expected) && actual == expected,
      }
  }
}

///|
async fn create_state(pinned_commit? : String) -> Json {
  create_recording.attempt += 1
  create_recording.phase = "input-validation"
  save_diagnostic("create-input", "received", source=Inputs)
  let mut attempt_complete = false
  errdefer (if !attempt_complete {
    save_diagnostic(
      "create-attempt",
      "failed",
      error_type="create_stage_failed",
    )
  })
  let document = read_document(environment("ORCA_REPO_PATH") + "/orca.yaml")
  let id = environment("ORCA_RECIPE_ID")
  let config = resolve_settings(document, id, name => @env.get_env_var(name))
  let recipes = match field(document, "environmentRecipes") {
    Some(Json::Array(items)) => items
    _ => []
  }
  let recipe = recipes.filter(item => {
      field(item, "id") == Some(Json::string(id))
    })[0]
  let mode = string_field(recipe, "checkoutMode", "recipe").unwrap_or(
    "orca-worktree",
  )
  save_diagnostic(
    "create-configuration",
    "received",
    source=Configuration(
      mode,
      if config.connection == Server {
        "orca-server"
      } else {
        "ssh"
      },
      config.build_ref,
    ),
  )
  guard mode == "orca-worktree" || mode == "provisioned-root" else {
    raise AdapterError("Invalid checkoutMode")
  }
  guard !(mode == "provisioned-root" && config.connection == Server) else {
    raise AdapterError("provisioned-root requires SSH")
  }
  guard valid_workspace_id(environment("ORCA_VM_INSTANCE_ID")) else {
    raise AdapterError("Invalid workspace identity")
  }
  if config.home is Some(home) {
    guard home.has_prefix("/") else {
      raise AdapterError("devsy.home must be absolute")
    }
  }
  if config.context is Some(context) {
    guard valid_context(context) else {
      raise AdapterError("Invalid devsy.context")
    }
  }
  if mode == "provisioned-root" {
    guard valid_commit(environment("ORCA_REPO_REF_HEAD")) else {
      raise AdapterError("Invalid provisioned-root commit")
    }
    let branch = environment("ORCA_REPO_BRANCH")
    guard !branch.has_prefix("-") else {
      raise AdapterError("Invalid provisioned-root branch")
    }
    ignore(
      command(
        "git",
        ["check-ref-format", "refs/heads/" + branch],
        "validate-branch",
      ),
    )
  }
  let build_ref = match config.build_ref {
    Some(value) if value != "" => value
    None if mode == "provisioned-root" =>
      @env.get_env_var("ORCA_REPO_REF")
      .filter(value => value != "")
      .unwrap_or(environment("ORCA_REPO_REF_HEAD"))
    _ => raise AdapterError("devsy.buildRef is required for orca-worktree")
  }
  let task_build = mode == "provisioned-root" && config.build_ref is None
  let state : Json = {
    "adapterVersion": 1,
    "workspaceId": environment("ORCA_VM_INSTANCE_ID"),
    "connection": if config.connection == Server {
      "orca-server"
    } else {
      "ssh"
    },
    "checkoutMode": mode,
    "codexAuth": config.codex_auth,
  }
  let locations = Json::empty_object()
  for name in location_variables {
    set_field(
      locations,
      name,
      match @env.get_env_var(name) {
        Some(value) => Json::string(value)
        None => Json::null()
      },
    )
  }
  set_field(state, "command", Json::array(config.command.map(Json::string)))
  set_field(state, "devsyEnv", locations)
  if config.home is Some(value) {
    set_field(state, "home", Json::string(value))
  }
  if config.context is Some(value) {
    set_field(state, "context", Json::string(value))
  }
  save_diagnostic("create-input", "success")
  create_recording.phase = "ref-resolution"
  let contexts = @json.parse(
    devsy(
      state,
      ["--result-format", "json", "context", "list"],
      "resolve-context",
    ),
  )
  guard contexts is Json::Array(context_items) else {
    raise AdapterError("Invalid Devsy context list")
  }
  let defaults = context_items.filter(item => {
    field(item, "default") == Some(Json::boolean(true))
  })
  guard defaults.length() == 1 else {
    raise AdapterError("No unique effective Devsy context")
  }
  set_field(state, "context", Json::string(required(defaults[0], "name")))
  let repository = match @env.get_env_var("ORCA_REPO_URL") {
    Some(url) if url != "" => url
    _ =>
      command(
        "git",
        ["-C", environment("ORCA_REPO_PATH"), "remote", "get-url", "origin"],
        "repository-remote",
      )
      .trim()
      .to_owned()
  }
  guard !repository.contains("?") && !repository.contains("#") else {
    raise AdapterError(
      "Repository URL must not contain credentials or query parameters",
    )
  }
  if repository.has_prefix("ssh://") {
    let authority = repository.split("/").to_array()[2]
    if authority.split_once("@") is Some((userinfo, _)) {
      guard !userinfo.contains(":") else {
        raise AdapterError("Repository URL must not contain credentials")
      }
    }
  }
  if repository.has_prefix("https://") || repository.has_prefix("http://") {
    guard !repository.split("/").to_array()[2].contains("@") else {
      raise AdapterError("Repository URL must not contain credentials")
    }
  }
  let default_output = command(
    "git",
    ["ls-remote", "--symref", "--", repository, "HEAD"],
    "resolve-default-branch",
  )
  let mut default_ref = None
  for line in default_output.split("\n") {
    if line.split_once("\t") is Some((reference, "HEAD")) &&
      reference.has_prefix("ref: refs/heads/") {
      default_ref = Some(reference[5:].to_owned())
    }
  }
  let lookup_ref = if build_ref.has_prefix("refs/remotes/origin/") {
    "refs/heads/" + build_ref[20:].to_owned()
  } else if build_ref.has_prefix("origin/") {
    "refs/heads/" + build_ref[7:].to_owned()
  } else if build_ref == "HEAD" {
    default_ref.unwrap_or("HEAD")
  } else {
    build_ref
  }
  let mut resolved_branch = None
  let mut hash = if valid_commit(lookup_ref) {
    lookup_ref
  } else {
    let resolved = command(
        "git",
        ["ls-remote", "--", repository, lookup_ref, lookup_ref + "^{}"],
        "resolve-build-ref",
      )
      .trim()
      .to_owned()
    let lines = resolved.split("\n").to_array()
    let peeled = lines.filter(line => line.has_suffix("^{}"))
    let selected = if peeled.length() == 1 && lines.length() <= 2 {
      peeled
    } else {
      lines
    }
    guard selected.length() == 1 &&
      selected[0].split_once("\t") is Some((commit, resolved_ref)) else {
      raise AdapterError("buildRef must resolve to one remote ref or commit")
    }
    if resolved_ref.has_prefix("refs/heads/") {
      resolved_branch = shallow_branch(resolved_ref.to_owned())
    }
    commit.to_owned()
  }
  guard valid_commit(hash) else {
    raise AdapterError("Invalid remote build commit")
  }
  if task_build && resolved_branch is None && default_ref is Some(reference) {
    let tip = command(
        "git",
        ["ls-remote", "--", repository, reference],
        "resolve-build-ref",
      )
      .trim()
      .to_owned()
    if tip.has_prefix(hash + "\t") {
      resolved_branch = shallow_branch(reference)
    }
  }
  save_diagnostic(
    "build-resolution",
    "success",
    source=Selection(
      build_ref,
      lookup_ref,
      resolved_branch,
      hash,
      if valid_commit(lookup_ref) {
        "literal-commit"
      } else {
        "remote-ref"
      },
    ),
  )
  let mut selection_reason = if task_build {
    "orca-input"
  } else {
    "configured-build-ref"
  }
  if task_build && hash != environment("ORCA_REPO_REF_HEAD") {
    selection_reason = "task-head-differs-from-ref"
    hash = environment("ORCA_REPO_REF_HEAD")
    resolved_branch = None
  }
  if pinned_commit is Some(commit) {
    selection_reason = "checkout-mismatch-retry"
    hash = commit
    resolved_branch = None
  }
  save_diagnostic(
    "build-selection",
    "success",
    source=Selection(
      build_ref, lookup_ref, resolved_branch, hash, selection_reason,
    ),
  )
  create_recording.phase = "build"
  set_field(state, "buildCommit", Json::string(hash))
  set_field(state, "buildRef", Json::string(build_ref))
  guard workspace(state) == None else {
    raise AdapterError("Workspace ID already exists")
  }
  for argument in config.up_args {
    guard ![
        "--id", "--uid", "--home", "--context", "--result-format", "--ide-launch",
        "--",
      ]
      .iter()
      .any(flag => argument == flag || argument.has_prefix(flag + "=")) else {
      raise AdapterError("upArgs cannot override adapter-owned options")
    }
  }
  let reservation = @fs.tmpdir(prefix="oe-create-")
  let uid = reservation.split("/").to_array().last().unwrap().to_owned() +
    "-" +
    @env.now().to_string()
  @fs.rmdir(reservation)
  set_field(state, "workspaceUid", Json::string(uid))
  errdefer discard_created_workspace(state)
  let create_args = fn(source : String, strategy : String) raise {
    [
      "--result-format",
      "json",
      "--uid",
      required(state, "workspaceUid"),
      "workspace",
      "up",
      source,
      "--id",
      required(state, "workspaceId"),
      "--ide-launch",
      "skip",
      "--git-clone-strategy=" + strategy,
    ] +
    config.up_args
  }
  let pinned_args = create_args(repository + "@sha256:" + hash, "")
  let native_source = match resolved_branch {
    Some(branch) => {
      ignore(
        command(
          "git",
          ["check-ref-format", "refs/heads/" + branch],
          "validate-build-branch",
        ),
      )
      repository + "@" + branch
    }
    None => repository + "@sha256:" + hash
  }
  let automatic_shallow = resolved_branch is Some(branch) &&
    (task_build || default_ref == Some("refs/heads/" + branch))
  let overridden = config.up_args
    .iter()
    .any(arg => {
      arg == "--git-clone-strategy" || arg.has_prefix("--git-clone-strategy=")
    })
  let strategy = if automatic_shallow && !overridden { "shallow" } else { "" }
  save_diagnostic(
    if overridden {
      "clone-override"
    } else if strategy == "shallow" {
      "clone-shallow"
    } else {
      "clone-full"
    },
    "started",
    source=Clone(
      resolved_branch,
      hash,
      if overridden {
        "override"
      } else if strategy == "shallow" {
        "shallow"
      } else {
        "full"
      },
      None,
