    strategy == "shallow" &&
    missing_shallow_commit(initial_output, hash) {
    save_diagnostic(
      "clone-fallback",
      "started",
      source=Clone(
        None,
        hash,
        if overridden {
          "override"
        } else {
          "full"
        },
        Some("missing-shallow-commit"),
      ),
    )
